package cl.felipe.agrofrost.domain.valueobject;
import cl.felipe.agrofrost.domain.model.FrostRiskLevel; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class FrostAssessmentTest { private final FieldId id=new FieldId("f-1"); private final MeasuredTemperature measured=new MeasuredTemperature(0); private final CriticalTemperature critical=new CriticalTemperature(0); @Test void retainsValueObjectsAndRisk() { FrostAssessment assessment=new FrostAssessment(id, measured, critical, FrostRiskLevel.CRITICAL); assertEquals(id, assessment.fieldId()); assertEquals(measured, assessment.measuredTemperature()); assertEquals(critical, assessment.criticalTemperature()); assertEquals(FrostRiskLevel.CRITICAL, assessment.riskLevel()); } @Test void rejectsNullComponents() { assertAll(() -> assertThrows(NullPointerException.class, () -> new FrostAssessment(null, measured, critical, FrostRiskLevel.SAFE)), () -> assertThrows(NullPointerException.class, () -> new FrostAssessment(id, null, critical, FrostRiskLevel.SAFE)), () -> assertThrows(NullPointerException.class, () -> new FrostAssessment(id, measured, null, FrostRiskLevel.SAFE)), () -> assertThrows(NullPointerException.class, () -> new FrostAssessment(id, measured, critical, null))); } }
